// ChoralRoot FM-1 layout tool: the preview module's loader (generated by tools/layout/build_layout.sh from
// tools/layout/crlayout.tpl.js: do not edit build/layout-web/crlayout.js). The WebAssembly module
// (tools/layout/layout_web.c: the whole firmware) is carried in this file as base64, so the page needs no fetch and
// works from file:// as well as from a server; crlayout.wasm beside it is the same bytes (node, other tools).
//   const ex = await CRLayoutModule.load();        the module's raw exports (lay_*: docs/LAYOUT-TOOL.md)
//   const ex = await CRLayoutModule.load(bytes);   .. from bytes read elsewhere (crlayout.wasm)
// web/fm1layout.js wraps the exports (strings, JSON, the picture).
(function (root) {
  const B64 = "/*WASM_B64*/";
  const VERSION = "/*VERSION*/";
  function bytes() {
    if (typeof Buffer !== "undefined") return new Uint8Array(Buffer.from(B64, "base64"));
    const s = atob(B64), u = new Uint8Array(s.length);
    for (let i = 0; i < s.length; i++) u[i] = s.charCodeAt(i);
    return u;
  }
  // the module is a standalone wasm (no Emscripten runtime): the few WASI calls the firmware's host side makes are
  // answered here. The clock is always 0 (the module runs on simulated time: nothing may depend on the wall clock),
  // text written to stdout (the firmware's trace lines) is dropped unless opts.stdout takes it.
  async function load(wasm, opts) {
    let mem;
    const out = opts && opts.stdout;
    const wasi = {
      clock_time_get: (id, prec, p) => { new DataView(mem.buffer).setBigUint64(p, 0n, true); return 0; },
      fd_write: (fd, iov, n, p) => {
        const dv = new DataView(mem.buffer);
        let len = 0;
        for (let i = 0; i < n; i++) {
          const a = dv.getUint32(iov + 8 * i, true), l = dv.getUint32(iov + 8 * i + 4, true);
          if (out) out(new Uint8Array(mem.buffer, a, l));
          len += l;
        }
        dv.setUint32(p, len, true);
        return 0;
      },
      proc_exit: () => {},
    };
    const stub = new Proxy(wasi, { get: (t, k) => (k in t ? t[k] : () => 0) });
    const env = new Proxy({}, { get: () => () => 0 });
    const { instance } = await WebAssembly.instantiate(wasm || bytes(), { wasi_snapshot_preview1: stub, env });
    mem = instance.exports.memory;
    if (instance.exports._initialize) instance.exports._initialize();
    return instance.exports;
  }
  root.CRLayoutModule = { load, bytes, version: VERSION };
})(typeof globalThis !== "undefined" ? globalThis : this);
